-- DiaMate research schema: foreign keys and indexes (run after loading)
ALTER TABLE research.records ADD CONSTRAINT fk_records_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.glucose_readings ADD CONSTRAINT fk_glucose_readings_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.glucose_readings ADD CONSTRAINT fk_glucose_readings_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
ALTER TABLE research.meals ADD CONSTRAINT fk_meals_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.meals ADD CONSTRAINT fk_meals_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
ALTER TABLE research.meal_items ADD CONSTRAINT fk_meal_items_meal_id FOREIGN KEY (meal_id) REFERENCES research.meals(meal_id);
ALTER TABLE research.meal_items ADD CONSTRAINT fk_meal_items_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.insulin_doses ADD CONSTRAINT fk_insulin_doses_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.insulin_doses ADD CONSTRAINT fk_insulin_doses_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
ALTER TABLE research.oral_medications ADD CONSTRAINT fk_oral_medications_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.oral_medications ADD CONSTRAINT fk_oral_medications_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
ALTER TABLE research.activity ADD CONSTRAINT fk_activity_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.ketones ADD CONSTRAINT fk_ketones_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.ketones ADD CONSTRAINT fk_ketones_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
ALTER TABLE research.timeline ADD CONSTRAINT fk_timeline_patient_id FOREIGN KEY (patient_id) REFERENCES research.patients(patient_id);
ALTER TABLE research.timeline ADD CONSTRAINT fk_timeline_record_id FOREIGN KEY (record_id) REFERENCES research.records(record_id);
